1	package zkcircuit
2	
3	import (
4		"errors"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// Regression tests for the circuit version on a committed trusted-setup
11	// record. A setup belongs exclusively to the frozen circuit version named in
12	// the record; any spelling the ordinary read would fill Version from names
13	// that one field: the canonical "version", an ASCII letter-case variant, a
14	// JSON-escaped spelling, or the Unicode-folded long-s "verſion" (U+017F). Two
15	// such spellings on one record make the version a function of key order
16	// (encoding/json keeps the last value) — with both versions of one circuit
17	// frozen, a record carrying 1 and 2 would read as v2's setup, hiding v1's
18	// setup while letting a v2 proof job pass the setup check. Such a record is
19	// refused as data corruption instead: equal or differing values, both legal,
20	// even with the name or another member interleaved, in either key order. A
21	// long-s spelling standing alone is still the single version field and keeps
22	// reading as it does today.
23	
24	// setupFieldIndent is the indentation of a setup record's own members as
25	// written by json.MarshalIndent with two-space indents (envelope → setups →
26	// record).
27	const setupFieldIndent = "\n      "
28	
29	// seedTwoFrozenSetupStore commits frozen c@1 and c@2 with a trusted setup on
30	// v1 only. It reproduces the ambiguity that matters: a setup for v1 whose
31	// record also spells version 2 reads as v2's setup, so v1's setup vanishes
32	// while a v2 job would pass the setup gate.
33	func seedTwoFrozenSetupStore(t *testing.T) string {
34		t.Helper()
35		dir := t.TempDir()
36		s, err := Open(dir)
37		if err != nil {
38			t.Fatal(err)
39		}
40		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1}); err != nil {
41			t.Fatal(err)
42		}
43		if _, err := s.CreateCircuit(Circuit{Name: "c", Version: 2, Constraints: 1}); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := s.FreezeCircuit("c", 1); err != nil {
47			t.Fatal(err)
48		}
49		if _, err := s.FreezeCircuit("c", 2); err != nil {
50			t.Fatal(err)
51		}
52		if _, err := s.RecordSetup("c", 1); err != nil {
53			t.Fatal(err)
54		}
55		if err := s.Close(); err != nil {
56			t.Fatal(err)
57		}
58		return dir
59	}
60	
61	// replaceInSetup scopes a literal replacement to the first record of the
62	// committed setups array: it finds the array marker and replaces the first
63	// occurrence of old after it, so the shared circuit "version" fields are
64	// never mistaken for a setup's own field.
65	func replaceInSetup(t *testing.T, dir, old, repl string) []byte {
66		t.Helper()
67		raw, err := readDataFile(t, dir)
68		if err != nil {
69			t.Fatal(err)
70		}
71		marker := `"setups": [`
72		at := strings.Index(string(raw), marker)
73		if at < 0 {
74			t.Fatalf("committed file does not carry the setups array")
75		}
76		rel := strings.Index(string(raw[at:]), old)
77		if rel < 0 {
78			t.Fatalf("setups array does not carry %q after its marker", old)
79		}
80		pos := at + rel
81		bad := string(raw[:pos]) + repl + string(raw[pos+len(old):])
82		writeDataFile(t, dir, []byte(bad))
83		return []byte(bad)
84	}
85	
86	// setupVersionLine is the single-line form of a setup's own version member,
87	// as written by the deterministic encoder.
88	func setupVersionLine(v int) string { return `"version": ` + strconv.Itoa(v) }
89	
90	// assertSetupVersionCorrupt opens dir, requires ErrDataCorrupt naming the
91	// setup record positionally and the version field, and checks the file is
92	// still byte-for-byte want.
93	func assertSetupVersionCorrupt(t *testing.T, dir string, want []byte) {
94		t.Helper()
95		_, err := Open(dir)
96		if !errors.Is(err, ErrDataCorrupt) {
97			t.Fatalf("want ErrDataCorrupt, got %v", err)
98		}
99		msg := err.Error()
100		if !strings.Contains(msg, "setup record #1") {
101			t.Fatalf("error does not locate the damaged setup record: %v", err)
102		}
103		if !strings.Contains(msg, "version") {
104			t.Fatalf("error does not name the version field: %v", err)
105		}
106		got, rerr := readDataFile(t, dir)
107		if rerr != nil {
108			t.Fatal(rerr)
109		}
110		if string(got) != string(want) {
111			t.Fatalf("open modified the damaged file")
112		}
113	}
114	
115	// A setup record carrying two recognized version spellings is refused:
116	// canonical plus an ASCII case variant or a JSON-escaped spelling, equal or
117	// differing values, both values legal, in either key order. The error locates
118	// the setup record and names the version field, and the file is left
119	// byte-for-byte in place.
120	func TestSetupVersionDuplicateIsCorrupt(t *testing.T) {
121		escV := jsonBackslash + "u0076ersion" // "version" as raw JSON text
122		escI := "vers" + jsonBackslash + "u0069on"
123		escUpperV := jsonBackslash + "u0056ERSION" // "VERSION" as raw JSON text
124		cases := []struct {
125			name string
126			frag string // replaces the single "version": 1 line in setup #1
127		}{
128			{"identical values, ASCII variant", `"version": 1, "VERSION": 1`},
129			{"differing values, ASCII variant", `"version": 1, "VERSION": 2`},
130			{"upper then canonical, differing", `"VERSION": 2, "version": 1`},
131			{"two non-canonical variants, same value", `"VERSION": 1, "Version": 1`},
132			{"two non-canonical variants, differing", `"VERSION": 2, "Version": 1`},
133			{"mixed case variant, same value", `"version": 1, "VeRsIoN": 1`},
134			{"escaped leading letter, same value", `"version": 1, "` + escV + `": 1`},
135			{"escaped inner letter, differing", `"version": 1, "` + escI + `": 2`},
136			{"escaped uppercase variant", `"version": 1, "` + escUpperV + `": 2`},
137			{"byte-identical duplicate", `"version": 1, "version": 1`},
138		}
139		for _, tc := range cases {
140			t.Run(tc.name, func(t *testing.T) {
141				dir := seedTwoFrozenSetupStore(t)
142				bad := replaceInSetup(t, dir, setupVersionLine(1), tc.frag)
143				assertSetupVersionCorrupt(t, dir, bad)
144				if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
145					t.Fatalf("reopen on ambiguous dir: want corruption, got %v", err)
146				}
147			})
148		}
149	}
150	
151	// The motivating ambiguity: both versions frozen and the v1 setup record
152	// spells version both 1 and 2. Without the uniqueness rule encoding/json keeps
153	// the last value and the setup reads against v2 — v1's setup disappears while
154	// a v2 job passes the setup gate. The read must instead be refused.
155	func TestSetupVersionAmbiguousBetweenTwoFrozenVersions(t *testing.T) {
156		dir := seedTwoFrozenSetupStore(t)
157		bad := replaceInSetup(t, dir, setupVersionLine(1), `"version": 1, "VERSION": 2`)
158		assertSetupVersionCorrupt(t, dir, bad)
159	}
160	
161	// The two version spellings need not be adjacent: a second spelling later in
162	// the record, with the name (or another member) sitting between them, is still
163	// a duplicate and is rejected.
164	func TestSetupVersionDuplicateInterspersedIsCorrupt(t *testing.T) {
165		dir := seedTwoFrozenSetupStore(t)
166		old := `"name": "c",` + setupFieldIndent + `"version": 1`
167		repl := `"version": 1,` + setupFieldIndent + `"name": "c",` + setupFieldIndent + `"VERSION": 2`
168		bad := replaceInSetup(t, dir, old, repl)
169		assertSetupVersionCorrupt(t, dir, bad)
170	}
171	
172	// A long-s "verſion" beside a canonical or ASCII spelling is a duplicate
173	// version field, direct or u017f-escaped, in either order and whether the two
174	// values agree. It must not fold its way into one silently-chosen version.
175	func TestSetupVersionLongSLookalikeBesideCanonicalIsCorrupt(t *testing.T) {
176		direct := "ver" + "ſ" + "ion"
177		escaped := "ver" + jsonBackslash + "u017f" + "ion"
178		cases := []struct {
179			name string
180			frag string
181		}{
182			{"canonical then direct, same value", `"version": 1, "` + direct + `": 1`},
183			{"direct then canonical, differing", `"` + direct + `": 2, "version": 1`},
184			{"canonical then escaped, same value", `"version": 1, "` + escaped + `": 1`},
185			{"escaped then ASCII variant, differing", `"` + escaped + `": 2, "VERSION": 1`},
186			{"direct beside ASCII variant", `"VERSION": 1, "` + direct + `": 2`},
187		}
188		for _, tc := range cases {
189			t.Run(tc.name, func(t *testing.T) {
190				dir := seedTwoFrozenSetupStore(t)
191				bad := replaceInSetup(t, dir, setupVersionLine(1), tc.frag)
192				assertSetupVersionCorrupt(t, dir, bad)
193			})
194		}
195	}
196	
197	// A single recognized version spelling keeps the current reading, including
198	// its ASCII case and long-s compatibility: the setup loads against the
199	// version named, direct or escaped, and stays exclusive to that name+version.
200	func TestSetupVersionSingleSpellingStillReads(t *testing.T) {
201		directLongS := "ver" + "ſ" + "ion"
202		escapedLongS := "ver" + jsonBackslash + "u017f" + "ion"
203		escS := "ver" + jsonBackslash + "u0073" + "ion"
204		cases := []struct {
205			name string
206			frag string
207		}{
208			{"canonical", `"version": 1`},
209			{"upper case", `"VERSION": 1`},
210			{"mixed case", `"VeRsIoN": 1`},
211			{"escaped letter", `"` + escS + `": 1`},
