221				if err != nil {
222					t.Fatalf("single spelling %q must load: %v", tc.name, err)
223				}
224				defer s.Close()
225				if _, found, err := s.GetSetup("c", 1); err != nil || !found {
226					t.Fatalf("single spelling %q lost v1 setup: found=%v err=%v", tc.name, found, err)
227				}
228				if _, found, err := s.GetSetup("c", 2); err != nil || found {
229					t.Fatalf("single spelling %q must not provide a v2 setup: found=%v err=%v", tc.name, found, err)
230				}
231				// A v1 job passes the setup gate; v2 still reports the setup
232				// missing.
233				if _, err := s.SubmitJob(boundProveJob("j1", "c", 1, "")); err != nil {
234					t.Fatalf("v1 job after single spelling %q: %v", tc.name, err)
235				}
236				if _, err := s.SubmitJob(boundProveJob("j2", "c", 2, "")); !errors.Is(err, ErrSetupMissing) {
237					t.Fatalf("v2 job after single spelling %q: want ErrSetupMissing, got %v", tc.name, err)
238				}
239			})
240		}
241	}
242	
243	// An illegal single version value is still rejected, exactly as before: a
244	// non-positive version names no circuit and fails the integrity validation.
245	func TestSetupVersionSingleIllegalValueStillRejected(t *testing.T) {
246		dir := seedTwoFrozenSetupStore(t)
247		replaceInSetup(t, dir, setupVersionLine(1), `"version": 0`)
248		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
